import {furnitureProfile} from './furniture-profiles.mjs';
import {EQUIPMENT,STARTERS,VARIANTS,furnitureKey} from './catalog.mjs';
import {equipmentStats,equipmentAvailability,progressForXP,MILESTONES,levelForXP} from './progression.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function artPreview(key,manifest){const s=manifest?.sprites?.[key],f=s&&manifest.files[s.sheet];return s?`<svg class="sprite-preview" viewBox="${s.rect.join(' ')}" aria-hidden="true"><image href="${f.file}" width="${f.width}" height="${f.height}"/></svg>`:'<span class="catalog-symbol">✧</span>';}
export function furniturePreview(item,manifest,equipmentId='manual_phoropter'){
 if(!manifest)return '<span class="catalog-symbol">✧</span>';let p;try{p=furnitureProfile(item,equipmentId);}catch{return '<span class="catalog-symbol">✧</span>';}
 const parts=p.previewLayers.filter(l=>(l.opacity??1)>0).map((l,n)=>{const s=manifest.sprites[l.key];if(!s)return null;const w=l.width,h=w*s.rect[3]/s.rect[2],reg=l.registration??[.5,1],x=l.offset[0]-w*reg[0],y=l.offset[1]-h*reg[1];return {s,w,h,x,y,n,l};}).filter(Boolean);
 if(!parts.length)return '<span class="catalog-symbol">✧</span>';const mount=p.previewMount,points=mount?[mount.from,mount.via,mount.to]:[],left=Math.min(...parts.map(p=>p.x),...points.map(([x])=>x-3)),top=Math.min(...parts.map(p=>p.y),...points.map(([,y])=>y-3)),right=Math.max(...parts.map(p=>p.x+p.w),...points.map(([x])=>x+3)),bottom=Math.max(...parts.map(p=>p.y+p.h),...points.map(([,y])=>y+3));
 const support=mount?`<g data-equipment-support="true" fill="none" stroke-linejoin="round" stroke-linecap="round"><path d="M${points.map(p=>p.join(',')).join(' L')}" stroke="#3b362d" stroke-width="5"/><path d="M${points.map(p=>p.join(',')).join(' L')}" stroke="#e6d3b3" stroke-width="3"/></g>`:'';
 return `<svg class="sprite-preview" viewBox="${left} ${top} ${right-left} ${bottom-top}" aria-hidden="true">${parts.map(({s,w,h,x,y,n,l})=>{const f=manifest.files[s.sheet],id='preview_'+l.key.replace(/[^a-z0-9]/gi,'_')+'_'+n,clip=s.outline?`<defs><clipPath id="${id}"><polygon points="${s.outline.map(([u,v])=>[s.rect[0]+u*s.rect[2],s.rect[1]+v*s.rect[3]].join(',')).join(' ')}"/></clipPath></defs>`:'';return `${n===1?support:''}<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${s.rect.join(' ')}">${clip}<image ${s.outline?`clip-path="url(#${id})"`:''} href="${f.file}" width="${f.width}" height="${f.height}"/></svg>`;}).join('')}</svg>`;
}
export function renderStarterCards(manifest){return ['trial_frame','manual_phoropter'].map(id=>{const e=EQUIPMENT.find(e=>e.id===id),s=equipmentStats(id);return `<button class="starter-card" data-action="starter" data-value="${id}"><span class="starter-art">${furniturePreview({kind:'exam',variantId:'default',rotation:0},manifest,id)}</span><strong>${e.name}</strong><span class="starter-wallet">✦ ${STARTERS[id].coins} starting coins</span><small>${s.duration}s exams · ${s.payout} coins per visit</small><small>${e.timeMultiplier.toFixed(2)}× time · ${e.moneyMultiplier.toFixed(2)}× earnings</small><span class="starter-detail">${id==='trial_frame'?'More room to decorate. Take your time.':'Quicker exams. A smaller starting wallet.'}</span><b>Begin with this kit →</b></button>`;}).join('');}
export function renderEquipment(c,manifest){return `<p class="panel-description">Smaller time multipliers mean faster exams. Own a kit once, switch for free.</p><div class="equipment-list">${EQUIPMENT.map(e=>{const a=equipmentAvailability(c,e.id),s=equipmentStats(e.id);return `<section class="equipment-card ${a.selected?'selected':''}"><div class="equipment-heading"><span class="equipment-preview">${furniturePreview({kind:'exam',variantId:'default',rotation:0},manifest,e.id)}</span><div><h3>${e.name}</h3><small>${s.duration}s exams · ${s.payout} coins per visit</small></div></div><p class="multipliers">${e.timeMultiplier.toFixed(2)}× time · ${e.moneyMultiplier.toFixed(2)}× earnings</p>${a.owned?`<button class="${a.selected?'secondary':'primary'} full" data-action="select-equipment" data-value="${e.id}" ${a.selected?'disabled':''}>${a.selected?'Selected for next visits':'Use owned kit · Free'}</button>`:`<p>${a.reason==='locked'?`Level ${e.unlockLevel} · ${a.xpRemaining} XP to unlock`:a.reason==='funds'?`Save ${e.price-c.coins} more coins`:'Ready for your practice'}</p><button class="primary full" data-action="buy-equipment" data-value="${e.id}" ${a.canBuy?'':'disabled'}>Buy · ✦ ${e.price}</button>`}</section>`;}).join('')}</div>`;}
export function renderMilestones(c){const p=progressForXP(c.xp);return `<span class="panel-eyebrow">ONE BRIGHTER DAY AT A TIME</span><h2>Your practice is growing.</h2><p class="panel-description">Level ${p.level} · ${c.xp} total XP. Every paid visit earns 10 XP.</p><div class="milestone-card"><strong>Level 1 · First light</strong><p>Starter kit and essential customization</p></div>${MILESTONES.map(m=>`<div class="milestone-card ${c.xp>=m.xp?'reached':''}"><span>${c.xp>=m.xp?'✓ Unlocked':`${m.xp-c.xp} XP to go`}</span><h3>Level ${m.level} · ${m.name}</h3><p>${m.unlocks}</p><small>${m.xp} total XP</small></div>`).join('')}${p.nextThreshold===null?'<p>All milestones reached. Your XP keeps growing!</p>':''}`;}
export function renderVariantOptions(c,item,manifest){const list=VARIANTS[item.kind]??[];if(list.length<2)return '';return `<section class="variant-section"><h3>Make it yours · free styles</h3><div class="variant-grid">${list.map(v=>{const locked=levelForXP(c.xp)<v.unlockLevel,selected=(item.variantId??'default')===v.id;return `<button class="variant-option ${selected?'selected':''}" data-action="variant" data-value="${esc(item.id??'candidate')}|${v.id}" ${locked||selected?'disabled':''}><span>${furniturePreview({...item,variantId:v.id},manifest)}</span><strong>${v.name}</strong><small>${locked?'Level '+v.unlockLevel:selected?'Selected':'Preview style'}</small></button>`;}).join('')}</div></section>`;}
